/* ================= Illustration kit ================= */
const lg=(id,stops,x2=0,y2=1)=>`<linearGradient id="${id}" x1="0" y1="0" x2="${x2}" y2="${y2}">${stops.map((c,i)=>`<stop offset="${(i/(stops.length-1)).toFixed(2)}" stop-color="${c}"/>`).join('')}</linearGradient>`;
const rg=(id,c,o=1)=>`<radialGradient id="${id}"><stop offset="0" stop-color="${c}" stop-opacity="${o}"/><stop offset="1" stop-color="${c}" stop-opacity="0"/></radialGradient>`;
const skyR=u=>`<rect width="400" height="300" fill="url(#${u}sky)"/>`;
const rot=(a,b,cx,cy,d)=>`<animateTransform attributeName="transform" type="rotate" values="${a} ${cx} ${cy};${b} ${cx} ${cy};${a} ${cx} ${cy}" dur="${d}s" repeatCount="indefinite"/>`;
const bob=(dy,d)=>`<animateTransform attributeName="transform" type="translate" additive="sum" values="0 0;0 ${dy};0 0" dur="${d}s" repeatCount="indefinite"/>`;
const drift=(dx,dy,d)=>`<animateTransform attributeName="transform" type="translate" values="0 0;${dx} ${dy}" dur="${d}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;1;0" keyTimes="0;.12;.88;1" dur="${d}s" repeatCount="indefinite"/>`;

function sun(u,x,y,r,c='#fff4c9'){return `<circle cx="${x}" cy="${y}" r="${r*3}" fill="url(#${u}glow)"><animate attributeName="r" values="${r*2.6};${r*3.3};${r*2.6}" dur="6s" repeatCount="indefinite"/></circle><circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`}
function moon(u,x,y,r,c='#fdf0c4'){return `<mask id="${u}mm"><rect width="400" height="300" fill="#fff"/><circle cx="${x+r*.45}" cy="${y-r*.28}" r="${r*.86}" fill="#000"/></mask><circle cx="${x}" cy="${y}" r="${r*3}" fill="url(#${u}mglow)"/><circle cx="${x}" cy="${y}" r="${r}" fill="${c}" mask="url(#${u}mm)"/>`}
function stars(n,seed,maxY=160,c='#fff8e0'){const r=rng(seed);let s='';for(let i=0;i<n;i++){const x=r()*400,y=r()*maxY,rad=r()*1.3+.4;s+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${rad.toFixed(2)}" fill="${c}"><animate attributeName="opacity" values="1;.25;1" dur="${(2+r()*3).toFixed(1)}s" begin="${(r()*3).toFixed(1)}s" repeatCount="indefinite"/></circle>`}return s}
const dunes=c=>`<path d="M0 196 Q70 166 150 188 T300 182 T400 176 V300H0Z" fill="${c[0]}"/><path d="M0 228 Q110 196 210 222 T400 210 V300H0Z" fill="${c[1]}"/><path d="M0 260 Q130 234 250 257 T400 248 V300H0Z" fill="${c[2]}"/>`;
const hills=c=>`<path d="M0 186 Q90 146 190 176 T400 166 V300H0Z" fill="${c[0]}"/><path d="M0 222 Q120 186 230 216 T400 202 V300H0Z" fill="${c[1]}"/><path d="M0 258 Q140 236 260 254 T400 246 V300H0Z" fill="${c[2]}"/>`;
/* Towering cumulus painted the way Japanese animated films paint them: a cool lilac shadow
   underneath, a soft mid tone, sunlit cream tops, and a faint haze ring so the edges feel soft. */
const PUFFS=[[-44,10,12],[-30,4,17],[-12,-8,22],[10,-22,27],[34,-10,21],[52,4,15],[14,2,24],[-2,-30,17],[26,-34,15]];
const CLOUD={day:['#fffaf0','#e9e7f3','#aab2dc'],warm:['#fff1dc','#f6dccd','#d9a7ae'],night:['#bdbbe6','#8784c0','#4b4886']};
const cloud=(x,y,s=1,d=40,tone='day')=>{const [lit,mid,sh]=CLOUD[tone];
  const ring=(dx,dy,k,c,op='')=>PUFFS.map(([cx,cy,r])=>`<circle cx="${cx+dx}" cy="${cy+dy}" r="${(r*k).toFixed(1)}" fill="${c}"${op}/>`).join('');
  return `<g><animateTransform attributeName="transform" type="translate" values="0 0;${d} 0;0 0" dur="60s" repeatCount="indefinite"/><g transform="translate(${x} ${y}) scale(${s})">${ring(0,2,1.14,lit,' opacity=".18"')}${ring(0,3,1,sh)}<rect x="-56" y="8" width="122" height="14" rx="7" fill="${sh}"/>${ring(-2,-1,.9,mid)}${ring(-4,-5,.7,lit)}<path d="M-38 -2 Q-28 -16 -14 -18 M0 -40 Q14 -52 30 -42 M30 -20 Q42 -26 52 -14" stroke="${lit}" stroke-width="2.4" fill="none" stroke-linecap="round" opacity=".85"/></g></g>`};
function palm(x,y,s=1,trunk='#7a5534',leaf='#2e7d5b'){const fr=[-175,-140,-100,-62,-25,12,195].map(a=>`<path d="M0 0 Q24 -14 48 5 Q25 -3 0 0Z" fill="${leaf}" transform="rotate(${a})"/>`).join('');return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M0 0 C5 -30 -4 -62 6 -92" stroke="${trunk}" stroke-width="7" fill="none" stroke-linecap="round"/><g transform="translate(6 -92)"><g>${rot(-4,4,0,0,6)}${fr}<circle cx="3" cy="4" r="3" fill="#8a4b2a"/><circle cx="-2" cy="5" r="3" fill="#9a5a30"/></g></g></g>`}
function well(x,y,s=1){return `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-27" y="-80" width="5" height="52" fill="#6b4a2b"/><rect x="22" y="-80" width="5" height="52" fill="#6b4a2b"/><path d="M-40 -78 L0 -104 L40 -78Z" fill="#a4553f"/><path d="M-40 -78 L40 -78 L36 -73 L-36 -73Z" fill="#7d3d2e"/><line x1="0" y1="-73" x2="0" y2="-46" stroke="#e7d3a6" stroke-width="1.5"/><rect x="-5" y="-48" width="10" height="8" rx="1.5" fill="#8a5f3b"/><path d="M-32 -30 L-30 4 Q0 10 30 4 L32 -30Z" fill="#c4935f"/><path d="M-31 -18 Q0 -12 31 -18 M-30 -6 Q0 0 30 -6" stroke="#a3764a" stroke-width="1.5" fill="none"/><path d="M-20 -29 v11 M2 -27 v11 M22 -29 v11 M-10 -17 v11 M12 -16 v11" stroke="#a3764a" stroke-width="1.5"/><ellipse cx="0" cy="-30" rx="32" ry="8" fill="#ddb07c"/><ellipse cx="0" cy="-30" rx="25" ry="5.5" fill="#24324d"/></g>`}

/* People are drawn as simple figures with no facial features.
   Each character gets their own silhouette (height, build, headwear, sash, cloak, staff)
   and poses carry the feeling, since there are no faces to do it.
   Shading follows anime cel painting: one flat shadow tone on the far side and a rim of light on the near edge. */
/* Manga-style emotion symbols (manpu): they show feelings without drawing a face. */
function emote(kind,x,y,s=1,flip){const pop=(d=0)=>`<animateTransform attributeName="transform" type="scale" additive="sum" values=".6;1.08;1;1;.6" keyTimes="0;.15;.25;.85;1" dur="3s" begin="${d}s" repeatCount="indefinite"/>`;
  const g=b=>`<g transform="translate(${x} ${y}) scale(${flip?-s:s} ${s})"><g>${pop()}${b}</g></g>`;
  if(kind==='sweat')return g(`<path d="M0 -8 Q6 0 4 5 Q0 9 -4 5 Q-6 0 0 -8Z" fill="#9fdcff" stroke="#3b6f9a" stroke-width="1"/><path d="M-1 -2 q-1 3 0 5" stroke="#fff" stroke-width="1.2" fill="none" stroke-linecap="round"/><path d="M9 -10 Q12 -5 11 -3 Q9 -1 7 -3 Q6 -5 9 -10Z" fill="#9fdcff" stroke="#3b6f9a" stroke-width=".8"/>`);
  if(kind==='surprise')return g(`<path d="M-2 -14 L2 -14 L1 2 L-1 2Z" fill="#e2463a" stroke="#7a1f18" stroke-width=".8"/><circle cx="0" cy="7" r="2.2" fill="#e2463a" stroke="#7a1f18" stroke-width=".8"/>${[-50,-20,10].map(a=>`<path d="M${(Math.cos(a*Math.PI/180)*10+8).toFixed(1)} ${(Math.sin(a*Math.PI/180)*10-4).toFixed(1)} l${(Math.cos(a*Math.PI/180)*6).toFixed(1)} ${(Math.sin(a*Math.PI/180)*6).toFixed(1)}" stroke="#e2463a" stroke-width="2" stroke-linecap="round"/>`).join('')}`);
  if(kind==='question')return g(`<text x="0" y="6" text-anchor="middle" font-family="Young Serif, Georgia, serif" font-size="20" font-weight="700" fill="#5a63c9" stroke="#2c2f6e" stroke-width=".6">?</text>`);
  if(kind==='idea')return g(`<circle r="7" fill="#ffe36b" stroke="#a8781a" stroke-width="1"/><rect x="-3" y="6" width="6" height="4" rx="1" fill="#b9b2a6"/>${[0,1,2,3,4].map(i=>`<path d="M0 -10 v-5" stroke="#ffd23b" stroke-width="2" stroke-linecap="round" transform="rotate(${-60+i*30})"/>`).join('')}`);
  if(kind==='joy')return g(`${[[0,-4,'#f7a8b8'],[10,4,'#ffe27a'],[-6,8,'#ffffff']].map(([a,b,c])=>`<g transform="translate(${a} ${b})">${[0,72,144,216,288].map(r=>`<ellipse cy="-3" rx="1.8" ry="3" fill="${c}" transform="rotate(${r})"/>`).join('')}<circle r="1.6" fill="#fff"/></g>`).join('')}`);
  if(kind==='love')return g(`<path d="M0 6 C-12 -2 -12 -12 -5 -12 C-2 -12 0 -10 0 -8 C0 -10 2 -12 5 -12 C12 -12 12 -2 0 6Z" fill="#ef7f8f" stroke="#8a2f3e" stroke-width="1"/>`);
  if(kind==='calm')return g(`<path d="M-8 0 q4 -6 8 0 t8 0" stroke="#7a8acb" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M-4 -8 q4 -6 8 0" stroke="#7a8acb" stroke-width="2" fill="none" stroke-linecap="round"/>`);
  return '';
}
const POSES={
  /* lean, head offset [dx,dy], back arm [elbow,hand], front arm [elbow,hand] (facing right) */
  stand:{b:[[-11,-36],[-12,-24]],f:[[10,-36],[11,-24]]},
  walk:{lean:4,b:[[-10,-37],[-15,-28]],f:[[12,-38],[20,-33]],step:1},
  tired:{lean:10,hd:[3,3],b:[[-10,-36],[-6,-27]],f:[[15,-44],[8,-58]],step:1},
  offer:{lean:4,b:[[8,-38],[22,-37]],f:[[13,-38],[27,-36]]},
  give:{lean:3,b:[[-10,-36],[-11,-24]],f:[[13,-40],[27,-40]]},
  shake:{b:[[-11,-36],[-12,-24]],f:[[12,-36],[22,-33]]},
  push:{lean:-5,hd:[-2,0],b:[[8,-38],[17,-46]],f:[[13,-40],[22,-47]],palm:true},
  dig:{lean:8,b:[[2,-44],[2,-56]],f:[[12,-40],[13,-33]]},
  climb:{b:[[-8,-58],[-1,-70]],f:[[9,-60],[1,-76]]},
  joy:{b:[[-15,-56],[-22,-70]],f:[[15,-56],[22,-70]],palm:true},
  raise:{b:[[-11,-36],[-12,-24]],f:[[14,-52],[17,-68]],palm:true},
  point:{lean:2,b:[[-11,-36],[-12,-24]],f:[[14,-46],[29,-49]]},
  heart:{hd:[1,-1],b:[[-11,-36],[-12,-24]],f:[[10,-34],[4,-40]]},
  look:{lean:-6,hd:[-1,-2],tilt:-18,b:[[-11,-34],[-14,-24]],f:[[10,-34],[4,-40]]},
  wonder:{lean:6,hd:[2,1],tilt:14,b:[[-12,-35],[-16,-28]],f:[[11,-36],[12,-24]]},
  kneel:{low:'kneel',lean:6,b:[[10,-30],[24,-26]],f:[[15,-28],[28,-24]]},
  cup:{low:'kneel',lean:14,hd:[3,2],tilt:16,b:[[10,-26],[17,-36]],f:[[15,-25],[20,-35]]},
  sit:{low:'sit',b:[[-10,-24],[-4,-16]],f:[[12,-26],[19,-33]]},
  sitTalk:{low:'sit',b:[[-10,-24],[-4,-16]],f:[[14,-30],[22,-42]],palm:true},
  dua:{hd:[1,2],tilt:10,b:[[10,-38],[22,-45]],f:[[14,-38],[27,-45]],palm:true},
  sitListen:{low:'sit',hd:[2,0],tilt:10,b:[[-10,-24],[-4,-16]],f:[[12,-26],[14,-18]]}
};
function person(x,y,s=1,o={}){
  const robe=o.robe||'#3f6fa3',wrap=o.wrap||'#f1e6cf',skin=o.skin||'#c98f63',P=POSES[o.pose||'stand']||POSES.stand;
  const dk=shade(robe,-.3),lt=shade(robe,.22),cel=shade(robe,-.2),rim=shade(robe,.5),sl=shade(robe,-.16),sk=shade(skin,-.18),tall=o.tall||1,wide=o.wide||1;
  const low=P.low, hy=low?-48:-62, [hdx,hdy]=P.hd||[0,0], hx=hdx, hyy=hy+hdy;
  const arm=([e,h],back)=>{const c=back?dk:sl,[ex,ey]=e,[px,py]=h,sx=back?-6:6,sy=low?-38:-50;
    return `<path d="M${sx} ${sy+2} L${ex} ${ey} L${px} ${py}" stroke="#3b2a33" stroke-width="9.2" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="M${sx} ${sy+2} L${ex} ${ey} L${px} ${py}" stroke="${c}" stroke-width="7" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`+
      (P.palm?`<ellipse cx="${px}" cy="${py}" rx="3" ry="4" fill="${back?sk:skin}"/>`:`<circle cx="${px}" cy="${py}" r="3.3" fill="${back?sk:skin}"/>`)};
  let body,feet='';
  if(low==='kneel')body=`<path d="M-12 -38 Q-19 -18 -17 0 L24 0 Q26 -9 14 -13 Q15 -26 12 -38 Q0 -44 -12 -38Z" fill="${robe}" stroke="#3b2a33" stroke-width="1.1" stroke-linejoin="round"/><path d="M-12 -38 Q-19 -18 -17 0 L-6 0 Q-9 -20 -4 -40Z" fill="${cel}"/><path d="M14 -13 Q24 -10 24 0 M12 -37 Q16 -26 14 -14" stroke="${rim}" stroke-width="2" fill="none" stroke-linecap="round"/>`+(o.sash?`<path d="M-15.6 -24 L13.5 -24 L13.4 -20 L-16 -20Z" fill="${o.sash}"/>`:'')+`<ellipse cx="-17" cy="-1.5" rx="6" ry="2.6" fill="#4a3424"/>`;
  else if(low==='sit')body=`<path d="M-12 -38 Q-17 -22 -16 -10 Q-26 -8 -26 0 L26 0 Q26 -8 16 -10 Q16 -24 12 -38 Q0 -44 -12 -38Z" fill="${robe}" stroke="#3b2a33" stroke-width="1.1" stroke-linejoin="round"/><path d="M-12 -38 Q-17 -22 -16 -10 Q-26 -8 -26 0 L-10 0 Q-8 -20 -4 -40Z" fill="${cel}"/>`+(o.sash?`<path d="M-15 -22 L15 -22 L15.3 -18 L-15.4 -18Z" fill="${o.sash}"/>`:'');
  else{const st=P.step?7:0;
    feet=`<ellipse cx="${-7-st/2}" cy="0" rx="6" ry="2.4" fill="#4a3424"/><ellipse cx="${8+st}" cy="${P.step?-1.5:0}" rx="6" ry="2.4" fill="#4a3424"/>`;
    body=`<path d="M-13 -50 Q-17 -24 -20 -1 Q-10 2 0 0 Q10 2 20 -1 Q17 -24 13 -50 Q0 -56 -13 -50Z" fill="${robe}" stroke="#3b2a33" stroke-width="1.1" stroke-linejoin="round"/><path d="M-13 -50 Q-17 -24 -20 -1 Q-14 1 -8 0 Q-10 -26 -5 -53Z" fill="${cel}"/><path d="M13 -48 Q16 -24 19 -2" stroke="${rim}" stroke-width="2.2" fill="none" stroke-linecap="round" opacity=".9"/><path d="M2 -40 Q4 -20 2 -2" stroke="${dk}" stroke-width="1.2" fill="none" opacity=".5"/>`+
      (o.cloak?`<path d="M-14 -51 Q-21 -24 -23 0 L-12 0 Q-10 -26 -6 -52Z" fill="${o.cloak}"/><path d="M-6 -52 Q-10 -26 -12 0" stroke="${o.trim||'#e2b64f'}" stroke-width="1.5" fill="none"/>`:'')+
      (o.sash?`<path d="M-16.4 -30 L16.4 -30 L16.8 -25.5 L-16.8 -25.5Z" fill="${o.sash}"/><path d="M-12 -26 L-15 -12 L-10 -13 L-9 -26Z" fill="${o.sash}"/>`:`<path d="M-16.4 -30 L16.4 -30 L16.8 -27 L-16.8 -27Z" fill="${dk}"/>`);}
  const hw=o.hat||'hood',H=hyy;
  let head=`<circle cx="${hx}" cy="${H}" r="9.5" fill="${hw==='kufi'?'#3a2a22':sk}" stroke="#3b2a33" stroke-width="1.1" stroke-linejoin="round"/><ellipse cx="${hx+2.2}" cy="${H+.5}" rx="7.6" ry="8.8" fill="${skin}"/><path d="M${hx+4.5} ${H-6} A8 8 0 0 1 ${hx+5} ${H+6}" stroke="${shade(skin,.2)}" stroke-width="1.8" fill="none" opacity=".6"/>`;
  if(hw==='veil')head=`<circle cx="${hx}" cy="${H}" r="9.5" fill="${skin}"/><path d="M${hx-12} ${H+2} Q${hx-13} ${H-14} ${hx} ${H-14} Q${hx+13} ${H-14} ${hx+12} ${H+2} Q${hx+14} ${H+14} ${hx+18} ${H+20} L${hx-18} ${H+20} Q${hx-14} ${H+14} ${hx-12} ${H+2}Z" fill="${wrap}"/><path d="M${hx-12} ${H+2} Q${hx-14} ${H+14} ${hx-18} ${H+20} L${hx-8} ${H+20}Z" fill="${shade(wrap,-.15)}"/><ellipse cx="${hx+2.5}" cy="${H+1}" rx="6.2" ry="7.4" fill="${skin}"/>`;
  else if(hw==='turban')head+=`<path d="M${hx-11} ${H-1} Q${hx-13} ${H-19} ${hx+1} ${H-19} Q${hx+14} ${H-18} ${hx+11} ${H-1} Q${hx} ${H-5} ${hx-11} ${H-1}Z" fill="${wrap}"/><path d="M${hx-10} ${H-6} Q${hx} ${H-15} ${hx+10} ${H-8} M${hx-9} ${H-11} Q${hx+1} ${H-18} ${hx+9} ${H-13}" stroke="${shade(wrap,-.2)}" stroke-width="1.3" fill="none"/><path d="M${hx-10} ${H-4} Q${hx-16} ${H+6} ${hx-13} ${H+14} L${hx-8} ${H+1}Z" fill="${shade(wrap,-.08)}"/>`;
  else if(hw==='kufi')head+=`<path d="M${hx-9} ${H-5} Q${hx-9} ${H-14} ${hx+1} ${H-14} Q${hx+10} ${H-14} ${hx+9} ${H-5}Z" fill="${wrap}"/><path d="M${hx-9} ${H-5} L${hx+9} ${H-5}" stroke="${shade(wrap,-.25)}" stroke-width="1.6"/>`;
  else if(hw==='cloth')head+=`<path d="M${hx-11} ${H} Q${hx-12} ${H-15} ${hx} ${H-15} Q${hx+12} ${H-15} ${hx+11} ${H-2} Q${hx+12} ${H+8} ${hx+9} ${H+14} L${hx+4} ${H+2} Q${hx-6} ${H-5} ${hx-6} ${H+4} L${hx-9} ${H+19} Q${hx-16} ${H+10} ${hx-11} ${H}Z" fill="${wrap}"/><path d="M${hx-10.5} ${H-8} Q${hx} ${H-13} ${hx+10.5} ${H-8}" stroke="${o.band||'#2b2420'}" stroke-width="2.6" fill="none"/>`;
  else head+=`<path d="M${hx-10.5} ${H-1} Q${hx-11} ${H-15} ${hx} ${H-15} Q${hx+11} ${H-15} ${hx+10.5} ${H-1} Q${hx} ${H-6} ${hx-10.5} ${H-1}Z" fill="${wrap}"/><path d="M${hx-9.5} ${H-3} Q${hx-15} ${H+8} ${hx-11} ${H+15} L${hx-6} ${H+2}Z" fill="${wrap}"/>`;
  if(P.tilt)head=`<g transform="rotate(${P.tilt} ${hx} ${H+8})">${head}</g>`;
  /* Chibi proportions, as in Japanese picture books: a big round head on a small body. */
  head=`<g transform="translate(${hx} ${H+9}) scale(1.32) translate(${-hx} ${-H-9})">${head}</g>`+(o.emote?emote(o.emote,hx+15,H-20,1,o.flip):'');
  const staff=o.staff?`<path d="M${low?20:-24} ${low?-64:-74} L${low?24:-26} 0" stroke="#7a5534" stroke-width="3" stroke-linecap="round"/>`:'';
  const tool=(o.pose==='dig')?`<path d="M-2 -70 L27 -2" stroke="#7a5534" stroke-width="3.5" stroke-linecap="round"/><path d="M21 -6 L35 -3 L32 8 L21 5Z" fill="#9aa4ad"/>`:'';
  const anim=o.bob?bob(-2,.8):'';
  const fig=`${staff}${arm(P.b,1)}${feet}${body}${head}${tool}${arm(P.f,0)}${o.hold||''}`;
  return `<g transform="translate(${x} ${y}) scale(${o.flip?-s:s} ${s})"><ellipse cx="2" cy="1" rx="${low?28:22}" ry="3.6" fill="#000" opacity=".14"/><g transform="scale(${wide} ${tall}) rotate(${P.lean||0})">${anim}${fig}</g></g>`;
}
const CAST={
  traveler:{robe:'#3f6fa3',hat:'turban',wrap:'#f4ead2',sash:'#a5683a'},
  buyer:{robe:'#5b8a4c',hat:'kufi',wrap:'#f3ecd8',cloak:'#8a6a45',trim:'#d9b45a',wide:1.12,tall:.93},
  seller:{robe:'#8a4f7d',hat:'cloth',wrap:'#ffffff',band:'#2b2420',sash:'#e2b64f',tall:1.1,wide:.9,skin:'#b98258'},
  wise:{robe:'#f2ece0',hat:'turban',wrap:'#ffffff',cloak:'#6b4a35',trim:'#e2b64f',staff:true,skin:'#a87856'},
  son:{robe:'#6f9e5c',hat:'kufi',wrap:'#ffffff',sash:'#d9b45a'},
  daughter:{robe:'#f6e6f0',hat:'veil',wrap:'#d9a8c8',skin:'#d2a07a'},
  umar:{robe:'#4f6b4a',hat:'turban',wrap:'#ffffff',cloak:'#7a5a3e',trim:'#c9a24a',tall:1.14,skin:'#c08a5e'},
  uwais:{robe:'#b59a72',hat:'hood',wrap:'#ddcba6',sash:'#7a5534',wide:.94,skin:'#9a6a48'},
  mother:{robe:'#7a6a9a',hat:'veil',wrap:'#efe6f4',skin:'#a87856',tall:.92}
};
const as=(who,o={})=>Object.assign({},CAST[who],o);
function dog(x,y,s=1,o={}){
  const c=o.c||'#c98a4e',d=shade(c,-.3),l=shade(c,.28),cel=shade(c,-.16),happy=o.mood==='happy',sad=o.mood==='thirsty';
  const shadow=`<ellipse cx="2" cy="1" rx="30" ry="3.5" fill="#000" opacity=".14"/>`;
  if(o.mood==='sleep')return `<g transform="translate(${x} ${y}) scale(${s})">${shadow}<g>${bob(-1,3)}<ellipse cx="0" cy="-10" rx="26" ry="11" fill="${c}"/><ellipse cx="-2" cy="-5" rx="20" ry="5" fill="${d}" opacity=".35"/><path d="M-24 -6 Q-36 4 -10 4 Q14 6 22 -2" stroke="${d}" stroke-width="5" fill="none" stroke-linecap="round"/><circle cx="22" cy="-12" r="10" fill="${c}"/><ellipse cx="31" cy="-8" rx="8" ry="5" fill="${c}"/><circle cx="38" cy="-9" r="2" fill="#2a1d17"/><path d="M16 -20 Q12 -10 18 -6 Q22 -12 22 -20Z" fill="${d}"/><path d="M22 -13 q2 2 4 0" stroke="#2a1d17" stroke-width="1.4" fill="none" stroke-linecap="round"/></g><text x="34" y="-26" font-family="Georgia" font-size="10" fill="#fff6d0">z<animate attributeName="opacity" values="0;1;0" dur="3s" repeatCount="indefinite"/></text><text x="42" y="-36" font-family="Georgia" font-size="13" fill="#fff6d0">z<animate attributeName="opacity" values="0;1;0" dur="3s" begin="1s" repeatCount="indefinite"/></text></g>`;
  const leg=(lx,lc,back)=>`<path d="M${lx-1} -22 Q${lx-2} -10 ${lx-1} -2 L${lx+5.5} -2 Q${lx+6} -12 ${lx+6} -22Z" fill="${lc}"/><ellipse cx="${lx+3.5}" cy="-1.6" rx="${back?4:4.6}" ry="2.2" fill="${shade(lc,-.15)}"/>`;
  const legs=leg(-18,d,1)+leg(8,d,1)+leg(-9,c)+leg(16,c);
  const eye=happy?`<path d="M26.5 -37.5 q2.3 -2.6 4.6 0" stroke="#2a1d17" stroke-width="1.6" fill="none" stroke-linecap="round"/>`
    :`<ellipse cx="29" cy="-36.5" rx="3.3" ry="4" fill="#2a1d17"/><ellipse cx="29" cy="-35" rx="2.2" ry="1.6" fill="#5a3a2a"/><circle cx="30.2" cy="-38" r="1.4" fill="#fff"/><circle cx="27.9" cy="-34.6" r=".6" fill="#fff"/>`+(sad?`<path d="M25.5 -42.5 Q29 -41.5 32 -43.5" stroke="#5a3a24" stroke-width="1.4" fill="none" stroke-linecap="round"/>`:'');
  const tongue=happy?`<path d="M37 -27 q1 5 4 4.5 q1.5 -3 -.5 -5Z" fill="#e8707e"/>`:`<path d="M37.5 -26.5 q1 9 5 8 q2 -4 -1 -9Z" fill="#e8707e">${bob(1.6,.45)}</path>`;
  const ear=sad?`<path d="M19 -42 Q11 -30 17 -22 Q23 -30 24 -42Z" fill="${d}"/>`:`<path d="M19 -43 Q13 -31 20 -27 Q25 -34 25 -44Z" fill="${d}">${happy?rot(-6,6,22,-43,.5):''}</path>`;
  const tilt=o.drink?'rotate(34 20 -30)':sad?'rotate(12 18 -30)':'';
  const head=`<g transform="${tilt}"><circle cx="26" cy="-34" r="11" fill="${c}"/><path d="M15 -34 A11 11 0 0 0 30 -23.8 Q19 -27 15 -34Z" fill="${cel}"/><path d="M31 -44 A11 11 0 0 1 36 -32" stroke="${l}" stroke-width="2" fill="none" opacity=".6"/><ellipse cx="36" cy="-30.5" rx="8.5" ry="5.8" fill="${c}"/><ellipse cx="37" cy="-28.6" rx="6" ry="3.4" fill="${l}"/><circle cx="44" cy="-32" r="2.4" fill="#2a1d17"/>${eye}<ellipse cx="31" cy="-29.5" rx="3.2" ry="1.8" fill="#f28a8a" opacity=".55"/>${o.emote?emote(o.emote,14,-58,.9,o.flip):''}${tongue}${ear}</g>`;
  const tail=sad?`<path d="M-22 -26 Q-32 -22 -34 -12" stroke="${c}" stroke-width="5" fill="none" stroke-linecap="round">${rot(-4,4,-22,-26,2.4)}</path>`
    :`<path d="M-22 -27 Q-36 -38 -32 -50" stroke="${c}" stroke-width="5" fill="none" stroke-linecap="round">${rot(-14,16,-22,-27,happy?.35:1.6)}</path>`;
  return `<g transform="translate(${x} ${y}) scale(${o.flip?-s:s} ${s})">${shadow}${tail}${legs}<ellipse cx="0" cy="-26" rx="25" ry="12" fill="${c}"/><path d="M-25 -26 A25 12 0 0 0 18 -17.7 Q-4 -21 -25 -26Z" fill="${cel}"/><path d="M-22 -30 Q0 -40 22 -30" stroke="${l}" stroke-width="2" fill="none" opacity=".5"/><ellipse cx="3" cy="-20" rx="15" ry="5.5" fill="${l}"/>${head}</g>`;
}
function cat(x,y,s=1,c='#41406e'){return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M10 -4 Q26 -2 22 -16" stroke="${c}" stroke-width="4" fill="none" stroke-linecap="round">${rot(-6,8,10,-4,3)}</path><ellipse cx="0" cy="-12" rx="12" ry="12" fill="${c}"/><circle cx="0" cy="-28" r="8" fill="${c}"/><path d="M-7 -32 L-6 -41 L-1 -35Z M7 -32 L6 -41 L1 -35Z" fill="${c}"/><path d="M-5 -28 q2 1.5 4 0 M1 -28 q2 1.5 4 0" stroke="#d9d4ff" stroke-width="1.1" fill="none" stroke-linecap="round"/></g>`}
function ant(x,y,s=1,o={}){
  const c=o.c||'#3a2620';
  const legs=[[-4,-8],[1,-4],[5,1]].map(([a,b])=>`<path d="M${a} -7 L${a-2} -3 L${b} 0" stroke="${c}" stroke-width="1.3" fill="none" stroke-linecap="round"/>`).join('');
  const ante=o.wave?`<g>${rot(-14,10,8,-15,.6)}<path d="M9 -15.5 Q11 -23 17 -23" stroke="${c}" stroke-width="1.2" fill="none" stroke-linecap="round"/></g>`:`<path d="M9 -15.5 Q11 -23 17 -23" stroke="${c}" stroke-width="1.2" fill="none" stroke-linecap="round"/>`;
  const call=o.call?`<ellipse cx="13.4" cy="-9" rx="1.5" ry="1.1" fill="#f6b3a6"/><g stroke="#fff3c8" stroke-width="1.3" fill="none" stroke-linecap="round"><path d="M19 -15 q3.5 4 0 8"><animate attributeName="opacity" values="0;1;0" dur="1.2s" repeatCount="indefinite"/></path><path d="M23 -18 q6 7 0 14"><animate attributeName="opacity" values="0;1;0" dur="1.2s" begin=".3s" repeatCount="indefinite"/></path></g>`:'';
  return `<g transform="translate(${x} ${y}) scale(${o.flip?-s:s} ${s})">${legs}<ellipse cx="-9" cy="-8" rx="7.5" ry="5.6" fill="${c}"/><ellipse cx="1" cy="-8" rx="4.5" ry="3.4" fill="${c}"/><circle cx="9" cy="-11" r="5" fill="${c}"/><ellipse cx="10.8" cy="-11.6" rx="2.3" ry="2.7" fill="#fff"/><ellipse cx="11.4" cy="-11.3" rx="1.5" ry="1.9" fill="#111"/><circle cx="11.9" cy="-12.2" r=".6" fill="#fff"/><ellipse cx="12.2" cy="-8.6" rx="1.4" ry=".8" fill="#f28a8a" opacity=".6"/><path d="M7.5 -15.5 Q7 -22 11 -24" stroke="${c}" stroke-width="1.2" fill="none" stroke-linecap="round"/>${ante}${call}</g>`;
}
function antLine(x1,x2,y,n,s,d,seed){const r=rng(seed);let g='';for(let i=0;i<n;i++){g+=`<g><animateTransform attributeName="transform" type="translate" values="${x1-x2} 0;0 0" dur="${d}s" begin="${(-i*d/n).toFixed(2)}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;1;0" keyTimes="0;.12;.85;1" dur="${d}s" begin="${(-i*d/n).toFixed(2)}s" repeatCount="indefinite"/>${ant(x2,y+(r()*4-2),s)}</g>`}return g}
function anthill(x,y,s=1,c='#b8804e'){return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M-44 0 Q-24 -32 0 -34 Q24 -32 44 0Z" fill="${c}"/><path d="M-32 -8 Q0 -16 32 -8 M-22 -20 Q0 -26 22 -20" stroke="${shade(c,-.18)}" stroke-width="1.2" fill="none"/><ellipse cx="0" cy="-30" rx="7" ry="3" fill="#3b2418"/><ellipse cx="-30" cy="-3" rx="7" ry="3.6" fill="#3b2418"/></g>`}
function grass(x,y,n,h,c,seed){const r=rng(seed);let g='';for(let i=0;i<n;i++){const gx=x+i*(6+r()*6),gh=h*(.6+r()*.6),b=(r()*16-8);g+=`<path d="M${gx} ${y} Q${gx+b/2} ${y-gh/2} ${gx+b} ${y-gh}" stroke="${c}" stroke-width="${(2+r()*2).toFixed(1)}" fill="none" stroke-linecap="round">${rot(-3,3,gx,y,(3+r()*3).toFixed(1))}</path>`}return g}
function tufts(n,seed,y1,y2,cols=['#5f9a3e','#8dc05a','#a9d46c']){const r=rng(seed);let g='';for(let i=0;i<n;i++){const x=r()*400,y=y1+r()*(y2-y1),h=5+r()*9*(y-y1+20)/(y2-y1+20),c=cols[i%cols.length];g+=`<path d="M${(x-3).toFixed(1)} ${y.toFixed(1)} q-1 ${(-h*.6).toFixed(1)} -4 ${(-h).toFixed(1)} M${x.toFixed(1)} ${y.toFixed(1)} q1 ${(-h*.7).toFixed(1)} 1 ${(-h*1.25).toFixed(1)} M${(x+3).toFixed(1)} ${y.toFixed(1)} q2 ${(-h*.6).toFixed(1)} 5 ${(-h*.95).toFixed(1)}" stroke="${c}" stroke-width="1.8" fill="none" stroke-linecap="round"/>`}return g}
function flowers(n,seed,y1,y2,cols){const r=rng(seed);let g='';for(let i=0;i<n;i++){const x=r()*400,y=y1+r()*(y2-y1),c=cols[i%cols.length];g+=`<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><line x1="0" y1="0" x2="0" y2="8" stroke="#3f7a44" stroke-width="1.2"/>${[0,72,144,216,288].map(a=>`<ellipse cx="0" cy="-3" rx="1.8" ry="3" fill="${c}" transform="rotate(${a})"/>`).join('')}<circle r="1.6" fill="#ffe27a"/></g>`}return g}
function birds(x,y,n,seed,c='#4a3f5c',dx=160,d=26){const r=rng(seed);let s='';for(let i=0;i<n;i++){const bx=x+r()*70-35,by=y+r()*34-17,sc=(.7+r()*.6).toFixed(2),du=(.45+r()*.3).toFixed(2);s+=`<g transform="translate(${bx.toFixed(1)} ${by.toFixed(1)}) scale(${sc})"><path d="M-7 0 Q-3.5 -5 0 0 Q3.5 -5 7 0" stroke="${c}" stroke-width="1.8" fill="none" stroke-linecap="round"><animate attributeName="d" values="M-7 0 Q-3.5 -5 0 0 Q3.5 -5 7 0;M-7 -3 Q-3.5 2 0 0 Q3.5 2 7 -3;M-7 0 Q-3.5 -5 0 0 Q3.5 -5 7 0" dur="${du}s" repeatCount="indefinite"/></path></g>`}return `<g>${drift(dx,-12,d)}${s}</g>`}
function banner(x,y,c,h=26){const a=`M0 ${-h} Q6 ${-h-3} 13 ${-h+1} L13 ${-h+9} Q6 ${-h+6} 0 ${-h+8}Z`,b=`M0 ${-h} Q6 ${-h+2} 13 ${-h-1} L13 ${-h+7} Q6 ${-h+10} 0 ${-h+8}Z`;return `<g transform="translate(${x} ${y})"><line x1="0" y1="0" x2="0" y2="${-h}" stroke="#5a4636" stroke-width="1.6"/><path d="${a}" fill="${c}"><animate attributeName="d" values="${a};${b};${a}" dur="1.6s" repeatCount="indefinite"/></path></g>`}
function army(x0,y,n,gap,cols,moving=true,c='#43507a'){let s='';for(let i=0;i<n;i++){const x=x0+i*gap;s+=`<g transform="translate(${x} ${y+(i%2)})"><path d="M-3.5 0 L-2.5 -10 Q0 -13 2.5 -10 L3.5 0Z" fill="${c}"/><circle cx="0" cy="-13.5" r="2.4" fill="${c}"/></g>`;if(i%4===1)s+=banner(x+3,y-2,cols[(i>>2)%cols.length],24)}return `<g>${moving?drift(40,0,22):''}${s}</g>`}
function palace(x,y,s=1,c='#efd9bd',g='#e7b54a'){return `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-50" y="-40" width="100" height="40" fill="${c}"/><rect x="-63" y="-72" width="13" height="72" fill="${c}"/><rect x="50" y="-72" width="13" height="72" fill="${c}"/><path d="M-63 -72 Q-56.5 -88 -50 -72Z M50 -72 Q56.5 -88 63 -72Z" fill="${g}"/><path d="M-26 -40 Q-26 -78 0 -84 Q26 -78 26 -40Z" fill="${g}"/><line x1="0" y1="-84" x2="0" y2="-96" stroke="${g}" stroke-width="2"/>${[-36,-18,18,36].map(wx=>`<path d="M${wx-4} -8 V-22 A4 4 0 0 1 ${wx+4} -22 V-8Z" fill="${shade(c,-.35)}"/>`).join('')}<path d="M-8 0 V-20 A8 8 0 0 1 8 -20 V0Z" fill="${shade(c,-.42)}"/></g>`}
function house(x,y,s=1,c='#e2b98a'){return `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-26" y="-38" width="52" height="38" fill="${c}"/><rect x="-29" y="-42" width="58" height="6" rx="1" fill="${shade(c,-.2)}"/><path d="M-7 0 V-15 A7 7 0 0 1 7 -15 V0Z" fill="#5a3b28"/><path d="M12 -20 V-27 A4 4 0 0 1 20 -27 V-20Z" fill="${o_win}"/></g>`}
let o_win='#5a3b28';
function tree(x,y,s=1){return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M-6 0 Q-3 -40 -5 -70 Q-20 -88 -42 -96 M-5 -70 Q8 -92 36 -100 M-3 -60 Q0 -90 2 -110" stroke="#6b4a32" stroke-width="7" fill="none" stroke-linecap="round"/><path d="M-9 0 L-11 -40 L3 -40 L7 0Z" fill="#6b4a32"/><g>${rot(-1,1,0,-100,7)}${[[-50,-104,34,16],[-14,-122,40,18],[30,-112,38,16],[0,-100,56,18],[-72,-96,22,10],[66,-104,24,11]].map(([cx,cy,rx,ry])=>`<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="#4f8a4a"/>`).join('')}<ellipse cx="-12" cy="-122" rx="28" ry="9" fill="#6aa65a"/><ellipse cx="32" cy="-116" rx="22" ry="7" fill="#6aa65a"/></g></g>`}
function jar(u,x,y,s=1,o={}){const c=o.c||'#c4673c';const gold=o.gold?`<path d="M-11 -41 Q0 -55 11 -41Z" fill="#ffcc3d"/>${[[-6,-44],[3,-47],[-1,-50],[6,-42],[-8,-41]].map(([a,b])=>`<ellipse cx="${a}" cy="${b}" rx="4.4" ry="2" fill="#ffdc5c" stroke="#c9961f" stroke-width=".7"/>`).join('')}`:'';
  return `<g transform="translate(${x} ${y}) scale(${s})">${o.glow?`<circle cx="0" cy="-34" r="60" fill="url(#${u}gold)"><animate attributeName="opacity" values=".65;1;.65" dur="2.8s" repeatCount="indefinite"/></circle>`:''}<path d="M-13 0 Q-25 -18 -14 -33 L-9 -38 L9 -38 L14 -33 Q25 -18 13 0Z" fill="${c}"/><path d="M-19 -21 Q0 -14 19 -21" stroke="${shade(c,.3)}" stroke-width="3" fill="none"/><path d="M-18 -14 Q0 -8 18 -14" stroke="${shade(c,-.25)}" stroke-width="1.5" fill="none" stroke-dasharray="3 3"/><path d="M-8 -30 Q-12 -20 -8 -10" stroke="${shade(c,.45)}" stroke-width="2.5" fill="none" stroke-linecap="round" opacity=".6"/><rect x="-11" y="-42" width="22" height="5" rx="2" fill="${shade(c,-.22)}"/>${gold}</g>`}
const sparkle=(x,y,r,d=0,c='#fff7d1')=>`<path transform="translate(${x} ${y})" d="M0 ${-r} L${r*.22} ${-r*.22} L${r} 0 L${r*.22} ${r*.22} L0 ${r} L${-r*.22} ${r*.22} L${-r} 0 L${-r*.22} ${-r*.22}Z" fill="${c}"><animate attributeName="opacity" values="0;1;0" dur="2.4s" begin="${d}s" repeatCount="indefinite"/></path>`;
function sparkles(n,seed,x1,y1,x2,y2,c){const r=rng(seed);let s='';for(let i=0;i<n;i++)s+=sparkle((x1+r()*(x2-x1)).toFixed(1),(y1+r()*(y2-y1)).toFixed(1),(3+r()*5).toFixed(1),(r()*2.4).toFixed(1),c);return s}
function hearts(n,x,y,seed,c='#ef7f8f'){const r=rng(seed);let s='';for(let i=0;i<n;i++){const hx=x+r()*50-25,d=(3+r()*2).toFixed(1),b=(-r()*4).toFixed(1),sc=(.9+r()*.8).toFixed(2);s+=`<g><animateTransform attributeName="transform" type="translate" values="0 0;${(r()*20-10).toFixed(0)} -60" dur="${d}s" begin="${b}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;0" dur="${d}s" begin="${b}s" repeatCount="indefinite"/><path transform="translate(${hx.toFixed(1)} ${y}) scale(${sc})" d="M0 3 C-6 -2 -6 -8 -2.5 -8 C-1 -8 0 -7 0 -6 C0 -7 1 -8 2.5 -8 C6 -8 6 -2 0 3Z" fill="${c}"/></g>`}return s}
function motes(n,seed,y1,y2,c='#ffe08a'){const r=rng(seed);let s='';for(let i=0;i<n;i++){const x=r()*400,y=y1+r()*(y2-y1),d=(4+r()*4).toFixed(1);s+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${(1+r()*1.6).toFixed(1)}" fill="${c}"><animate attributeName="opacity" values="0;1;0" dur="${d}s" begin="${(-r()*4).toFixed(1)}s" repeatCount="indefinite"/><animateTransform attributeName="transform" type="translate" values="0 0;${(r()*20-10).toFixed(0)} -18;0 0" dur="${d}s" repeatCount="indefinite"/></circle>`}return s}
const shoe=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-9 0 L-9 -11 Q-9 -15 -5 -15 L1 -15 L1 -6 Q9 -6 13 -2 L13 0Z" fill="#7b4b2a"/><ellipse cx="-4" cy="-15" rx="5" ry="1.8" fill="#6fc3e6"/><path d="M-9 -2 L13 -2" stroke="#5c3720" stroke-width="1.5"/></g>`;
const heat=(x,y)=>`<path d="M${x} ${y} q5 -5 10 0 t10 0 t10 0" stroke="#fff6e0" stroke-width="1.6" fill="none" opacity=".0"><animate attributeName="opacity" values="0;.7;0" dur="2.6s" begin="${(x%7)/3}s" repeatCount="indefinite"/><animateTransform attributeName="transform" type="translate" values="0 0;0 -10" dur="2.6s" begin="${(x%7)/3}s" repeatCount="indefinite"/></path>`;
function rays(cx,cy,n,len,c,op=.35,a0=-160,a1=-20){let s='';for(let i=0;i<n;i++){const a=(a0+i*((a1-a0)/(n-1)))*Math.PI/180,a2=a+.07;s+=`<polygon points="${cx},${cy} ${(cx+Math.cos(a)*len).toFixed(1)},${(cy-Math.sin(a)*-len).toFixed(1)} ${(cx+Math.cos(a2)*len).toFixed(1)},${(cy-Math.sin(a2)*-len).toFixed(1)}" fill="${c}"/>`}return `<g opacity="${op}"><animate attributeName="opacity" values="${op};${op*.45};${op}" dur="5s" repeatCount="indefinite"/>${s}</g>`}
function lanternString(y0,sag,n,cols,W=400){let s=`<path d="M-10 ${y0} Q${W/2} ${y0+sag*2} ${W+10} ${y0}" stroke="#d9b56b" stroke-width="1.2" fill="none"/>`;for(let i=1;i<=n;i++){const t=i/(n+1),x=-10+(W+20)*t,y=(1-t)*(1-t)*y0+2*(1-t)*t*(y0+sag*2)+t*t*y0,c=cols[i%cols.length],len=8+(i%3)*7;s+=`<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><g>${rot(-6,6,0,0,3+i%3)}<line x1="0" y1="0" x2="0" y2="${len}" stroke="#d9b56b" stroke-width="1"/><circle cx="0" cy="${len+13}" r="17" fill="${c}" opacity=".22"/><path d="M-5 ${len} L5 ${len} L7.5 ${len+7} L4.5 ${len+20} L-4.5 ${len+20} L-7.5 ${len+7}Z" fill="${c}"/><path d="M-2 ${len+8} L2 ${len+8} L2 ${len+17} L-2 ${len+17}Z" fill="#fff6cf" opacity=".95"/><rect x="-3" y="${len+20}" width="6" height="3" fill="#b38a3a"/><path d="M-2 ${len} Q0 ${len-5} 2 ${len}" fill="${c}"/></g></g>`}return s}
function starPts(r1,r2,n=8){const p=[];for(let i=0;i<n*2;i++){const a=Math.PI*i/n-Math.PI/2,r=i%2?r2:r1;p.push((Math.cos(a)*r).toFixed(2)+','+(Math.sin(a)*r).toFixed(2))}return p.join(' ')}
function valueIcon(icon,u){
  if(icon==='paw')return `<g fill="#5a3410"><ellipse cx="0" cy="8" rx="13" ry="11"/><ellipse cx="-15" cy="-7" rx="5.5" ry="7" transform="rotate(-20 -15 -7)"/><ellipse cx="-5" cy="-15" rx="5.5" ry="7.5"/><ellipse cx="6" cy="-15" rx="5.5" ry="7.5"/><ellipse cx="16" cy="-6" rx="5.5" ry="7" transform="rotate(20 16 -6)"/></g>`;
  if(icon==='ant')return ant(-2,12,2.1,{c:'#5a3410'});
  if(icon==='hands')return `<g fill="#5a3410">${[-1,1].map(m=>`<g transform="scale(${m} 1) translate(10 4) rotate(-14)"><rect x="-8" y="-4" width="16" height="20" rx="7"/>${[-7.5,-3,1.5,6].map((fx,i)=>`<rect x="${fx-.5}" y="${-17+Math.abs(i-1.5)*2}" width="4.4" height="16" rx="2.2"/>`).join('')}<rect x="-12" y="-1" width="4.4" height="11" rx="2.2" transform="rotate(-30 -10 8)"/></g>`).join('')}</g>`;
  if(icon==='jar')return jar(u,0,22,.95,{c:'#8a3f1e',gold:true});
  return `<path d="M0 20C-22 4-24-14-12-20C-4-24 0-16 0-12C0-16 4-24 12-20C24-14 22 4 0 20Z" fill="#5a3410"/>`;
}
function badge(u,icon,size=1){return `<g transform="scale(${size})"><polygon points="${starPts(46,37)}" fill="url(#${u}bdg)" stroke="#fff3c4" stroke-width="2"/><polygon points="${starPts(40,32)}" fill="none" stroke="#a8701a" stroke-width="1.2" opacity=".7"/><circle r="27" fill="#ffe7a6" stroke="#c98a1f" stroke-width="1.5"/>${valueIcon(icon,u)}</g>`}
function badgeSvg(icon){const u='b'+(UID++)+'_';return `<svg viewBox="-50 -50 100 100" aria-hidden="true"><defs>${lg(u+'bdg',['#ffe08a','#f2b84b','#c8841c'])}${rg(u+'gold','#ffd451',.9)}</defs>${badge(u,icon)}</svg>`}

/* Camels for the travellers from Yemen: kawaii eye and blush, as with the other animals. */
function camel(x,y,s=1,o={}){
  const c=o.c||'#d6a46a',d=shade(c,-.25),l=shade(c,.25),walk=o.walk;
  const leg=(lx,back,i)=>`<g>${walk?rot(back?8:-8,back?-8:8,lx+2,-40,1.4):''}<path d="M${lx} -40 L${lx-1} -3 L${lx+5} -3 L${lx+5} -40Z" fill="${back?d:c}"/><ellipse cx="${lx+2.5}" cy="-2" rx="4.4" ry="2.2" fill="${shade(c,-.4)}"/></g>`;
  const load=o.load?`<path d="M-20 -58 Q-4 -66 14 -58 L16 -42 Q-2 -36 -22 -42Z" fill="${o.load}"/><path d="M-21 -44 Q-3 -38 15 -44" stroke="#fff3c4" stroke-width="2" fill="none" stroke-dasharray="3 3"/>${[-18,-8,2,12].map(t=>`<line x1="${t}" y1="-40" x2="${t}" y2="-33" stroke="${o.load}" stroke-width="2"/>`).join('')}`:'';
  return `<g transform="translate(${x} ${y}) scale(${o.flip?-s:s} ${s})"><ellipse cx="0" cy="0" rx="32" ry="3.6" fill="#000" opacity=".14"/>${leg(-22,1)}${leg(10,1)}${leg(-14)}${leg(18)}<g>${walk?bob(-1.5,.7):''}<path d="M-30 -44 Q-34 -58 -20 -60 Q-8 -86 6 -62 Q20 -64 28 -52 Q30 -40 18 -38 L-22 -38 Q-30 -38 -30 -44Z" fill="${c}"/><path d="M-12 -74 Q-4 -80 2 -70" stroke="${l}" stroke-width="2.4" fill="none" opacity=".7"/><path d="M-30 -46 Q-38 -42 -36 -30" stroke="${c}" stroke-width="3" fill="none" stroke-linecap="round">${rot(-8,8,-30,-46,2)}</path>${load}<path d="M22 -54 Q34 -60 34 -78 Q34 -88 40 -90 L46 -86 Q42 -80 42 -72 Q42 -54 28 -44Z" fill="${c}"/><ellipse cx="46" cy="-86" rx="11" ry="6.5" fill="${c}"/><ellipse cx="53" cy="-83" rx="5" ry="4" fill="${l}"/><path d="M38 -92 q-3 -5 1 -6 q2 2 1 6Z" fill="${d}"/><ellipse cx="45" cy="-88" rx="2.2" ry="2.8" fill="#2a1d17"/><circle cx="45.8" cy="-89" r=".8" fill="#fff"/><ellipse cx="47" cy="-83" rx="2.4" ry="1.3" fill="#f28a8a" opacity=".55"/><path d="M53 -81 q2 1 3.5 0" stroke="#2a1d17" stroke-width="1" fill="none" stroke-linecap="round"/></g></g>`;
}
/* Tall mud-brick tower houses of Yemen, with white trim and arched windows. */
function towerHouse(x,y,s=1,c='#b8794e',h=90){return `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-20" y="${-h}" width="40" height="${h}" fill="${c}"/><rect x="-20" y="${-h}" width="9" height="${h}" fill="${shade(c,-.15)}"/><path d="M-22 ${-h} h44 v-5 h-6 v-4 h-6 v4 h-8 v-4 h-6 v4 h-8 v-4 h-6 v4 h-4Z" fill="${shade(c,-.1)}"/>${[...Array(Math.floor(h/26))].map((_,i)=>{const wy=-h+12+i*26;return `<path d="M-23 ${wy+16} h46" stroke="#fff6e6" stroke-width="1.6"/>`+[-9,7].map(wx=>`<path d="M${wx-4} ${wy+10} V${wy+4} A4 4 0 0 1 ${wx+4} ${wy+4} V${wy+10}Z" fill="#4a2e1e"/><path d="M${wx-5.5} ${wy+4} A5.5 5.5 0 0 1 ${wx+5.5} ${wy+4}" stroke="#fff6e6" stroke-width="1.6" fill="none"/>`).join('')}).join('')}<path d="M-5 0 V-12 A5 5 0 0 1 5 -12 V0Z" fill="#4a2e1e"/></g>`}
function mudHouse(x,y,s=1,c='#d9b48a'){return `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-18" y="-24" width="36" height="24" rx="2" fill="${c}"/><rect x="-18" y="-24" width="8" height="24" fill="${shade(c,-.14)}"/><path d="M-20 -24 h40" stroke="${shade(c,-.25)}" stroke-width="3"/>${[-12,-4,4,12].map(t=>`<line x1="${t}" y1="-26" x2="${t+1}" y2="-22" stroke="#6b4a32" stroke-width="1.6"/>`).join('')}<path d="M-4 0 V-10 A4 4 0 0 1 4 -10 V0Z" fill="#5a3b28"/><rect x="8" y="-17" width="5" height="5" fill="${o_win}"/></g>`}
const scroll=(x,y)=>`<g transform="translate(${x} ${y})"><rect x="-5" y="-9" width="10" height="18" rx="2" fill="#fbf0d6" stroke="#b08a52" stroke-width="1"/><rect x="-6.5" y="-11" width="13" height="4" rx="2" fill="#d9b56b"/><rect x="-6.5" y="7" width="13" height="4" rx="2" fill="#d9b56b"/><path d="M-2.5 -3 h5 M-2.5 0 h5 M-2.5 3 h4" stroke="#8a6a45" stroke-width=".8"/></g>`;

